import re as _re
def _pretty(n):
    m = _re.match(r"^(\d{3,4})\s*-\s*(\d{3,4})?\s*([^,]+),\s*(.+)$", n)
    return f"{m.group(4)} {m.group(3)} ({m.group(1)}\u2013{m.group(2) or ''})" if m else n
for _a in authors.values(): _a["name"] = _pretty(_a["name"])

