_SN_PLAYER_JS = '<script>(function(){var DATA=__SN_DATA__;\nfunction fmt(s){s=Math.floor(s);var h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;\nreturn (h?h+":"+String(m).padStart(2,"0"):m)+":"+String(x).padStart(2,"0")}\nfunction key(id){return "rv.audio."+id}\ndocument.querySelectorAll(".rv-listen").forEach(function(btn){\nbtn.addEventListener("click",function(){\nvar id=btn.dataset.ident,\npanel=document.getElementById("rv-"+id),audio=panel.querySelector("audio"),\nlist=panel.querySelector(".rv-tracks"),now=panel.querySelector(".rv-now"),\ndl=panel.querySelector(".rv-dl"),speed=panel.querySelector(".rv-speed");\nif(panel.hidden){\npanel.hidden=false;btn.textContent="▾ Thu gọn";\nif(!list.children.length){\nDATA[id].forEach(function(p,i){var li=document.createElement("li"),\nb=document.createElement("button");b.type="button";\nb.innerHTML="<span></span><span></span>";b.firstChild.textContent=p.l;\nb.lastChild.textContent=p.d;b.dataset.i=i;li.appendChild(b);list.appendChild(li)});\nvar saved=null;try{saved=JSON.parse(localStorage.getItem(key(id)))}catch(e){}\nif(saved&&DATA[id][saved.i])play(saved.i,saved.t);else play(0,0);\n}\n}else{\npanel.hidden=true;btn.textContent="▶ Nghe ngay";audio.pause();return;\n}\nfunction play(i,t){var p=DATA[id][i];\ndocument.querySelectorAll("audio").forEach(function(a){if(a!==audio)a.pause()});\nif(audio.dataset.i!=i){audio.src=p.u;audio.dataset.i=i}\naudio.playbackRate=parseFloat(speed.value);\nif(t)audio.currentTime=t;audio.play().catch(function(){});\nnow.textContent="Đang nghe: "+p.l+" · "+p.d;dl.href=p.u;\nlist.querySelectorAll("button").forEach(function(b){b.classList.toggle("on",+b.dataset.i===i)})}\nif(!panel.dataset.wired){\npanel.dataset.wired="1";\nlist.addEventListener("click",function(e){var b=e.target.closest("button");if(b)play(+b.dataset.i,0)});\nspeed.addEventListener("change",function(){audio.playbackRate=parseFloat(speed.value)});\naudio.addEventListener("ended",function(){var i=+audio.dataset.i+1;\nif(DATA[id][i])play(i,0);else{now.textContent="Đã nghe hết cuốn sách.";\ntry{localStorage.removeItem(key(id))}catch(e){}}});\nvar last=0;audio.addEventListener("timeupdate",function(){var n=Date.now();\nif(n-last<5000)return;last=n;\ntry{localStorage.setItem(key(id),JSON.stringify({i:+audio.dataset.i,t:audio.currentTime}))}catch(e){}});\naudio.addEventListener("pause",function(){\ntry{localStorage.setItem(key(id),JSON.stringify({i:+audio.dataset.i,t:audio.currentTime}))}catch(e){}});\n}\n})})})()</script>'
# Sách nói của Thư Viện Cải Chánh: the book grid is rendered from
