sm = "".join(f"<url><loc>{SITE}/{u}</loc></url>" for u in urls)
# Preserve sitemap entries owned by the hub generators (scripts/build_*.py):
# build-pages owns only its own inventory and must never drop foreign entries
# (incident 2026-11-06: a catalog run wiped all hub-module URLs from the sitemap).
try:
    _prev = open("sitemap.xml", encoding="utf-8").read()
    _own = {f"{SITE}/{u}" for u in urls}
    _hub = ("/kinh-thanh/", "/giao-ly/", "/bach-khoa/", "/suy-ngam/", "/hoc-vien/", "/hoi-dap/", "/bai-giang/", "/thanh-ca/", "/tap-chi/", "/danh-ba/", "/tim-kiem/", "/hub.html")
    _keep = []
    for _e in re.findall(r"<url>.*?</url>", _prev):
        _m = re.search(r"<loc>([^<]+)</loc>", _e)
        if _m and _m.group(1) not in _own and any(_p in _m.group(1) for _p in _hub):
            _keep.append(_e)
    sm += "".join(_keep)
except OSError:
    pass
# Drop nhom-nho entries whose page does not exist in this tree: the plan
# generator's catalogue can list books whose generated pages never landed
# in the repo (2026-11-09 sweep: 1,295 of 2,205 listed /nhom-nho/ URLs
# returned 404). Same precedent as the author-link cleanup above.
# Sitemap must describe what is LIVE (committed to main), not what this run
# just generated in the working tree. The catalog bot (catalog.yml) runs this
# script in a full checkout where nang_cap3.py regenerates every nhom-nho/*.html
# from txt/, but its `git add -A` list does NOT include nhom-nho/ — so the
# generated pages never reach the repo while the sitemap listed all of them
# (the 2026-11-09 fix regressed within one bot run: 917 -> 2,212 entries).
# Hence the check below uses the git-tracked file set, falling back to the
# working tree only if git is unavailable.
def _tracked(_dir):
    try:
        import subprocess
        _out = subprocess.check_output(["git", "ls-files", "--cached", "--", _dir + "/"], text=True, timeout=120)
        return {_dir + "/" + _l for _l in _out.splitlines() if _l}
    except Exception:
        return None
_tracked_nh = _tracked("nhom-nho")
def _sm_alive(_m):
    _loc = re.search(r"<loc>([^<]+)</loc>", _m.group(0)).group(1)
    if "/nhom-nho/" in _loc and _loc.startswith(SITE + "/"):
        _rel = _loc[len(SITE) + 1:]
        if _tracked_nh is not None:
            return _m.group(0) if _rel in _tracked_nh else ""
        return _m.group(0) if os.path.exists(_rel) else ""
    return _m.group(0)
sm = re.sub(r"<url>.*?</url>", _sm_alive, sm)
# Add live pages the generators no longer emit but which are still tracked in
# the repo: nhom-nho pages whose books left the catalogue, and the static
# /sach/ book pages (no generator owns them).
for _dir in ("nhom-nho", "sach"):
    _tr = _tracked_nh if _dir == "nhom-nho" else _tracked("sach")
    if _tr is None:
        continue
    _have = set(re.findall(r"<loc>([^<]+)</loc>", sm))
    for _rel in sorted(_r for _r in _tr if _r.endswith(".html")):
        _u = f"{SITE}/{_rel}"
        if _u not in _have:
            sm += f"<url><loc>{_u}</loc></url>"
# Dedupe <loc>s (e.g. the same /ban-dich/ URL emitted twice when a book sits
# in two catalogue entries — spurgeon-sermons-vol23), keeping first occurrence.
_seen, _out = set(), []
for _e in re.findall(r"<url>.*?</url>", sm):
    _m = re.search(r"<loc>([^<]+)</loc>", _e)
    if _m and _m.group(1) not in _seen:
        _seen.add(_m.group(1)); _out.append(_e)
sm = "".join(_out)
# The full-library page is hand-maintained, not generated here; keep it listed.
if f"{SITE}/thu-vien.html" not in sm:
    sm += f"<url><loc>{SITE}/thu-vien.html</loc></url>"
open("sitemap.xml", "w", encoding="utf-8").write(f'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">{sm}</urlset>\n')
